<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT b.*,t.table_no FROM bills b LEFT JOIN restaurant_tables t ON t.id=b.table_id WHERE b.id=?');$s->execute([$id]);$b=$s->fetch();if(!$b)die('Bill not found');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>KOT <?=e($b['bill_no'])?></title><style>body{font-family:Arial;width:300px;margin:auto}table{width:100%;border-collapse:collapse}td,th{padding:6px;border-bottom:1px dashed #aaa}@media print{.no-print{display:none}}</style></head><body><h2 style="text-align:center">KITCHEN ORDER (KOT)</h2><p>Bill: <?=e($b['bill_no'])?><br>Table: <?=e($b['table_no']?:'Take Away')?><br>Time: <?=e($b['created_at'])?></p><table><tr><th>Item</th><th>Qty</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['quantity'])?></td></tr><?php endforeach;?></table><p class="no-print"><button onclick="print()">Print</button></p><script>window.onload=()=>window.print()</script></body></html>
